SourceCode.Declaration:
/// <summary>
/// Controller class for ER price list report
/// </summary>
class AVAERPriceListController extends ERFormatMappingRunBaseController
{
}

Method.Source:
/// <summary>
/// The main entrance of the controller
/// </summary>
/// <param name = "args">The arguments</param>
public static void main(Args args)
{
    if(!AVASalesParameters::find().ERPriceListFormat)
    {
        throw Error(strFmt("@NDX:NXAERPriceListReportError", "@NDX:NXASalesParameters", "@NDX:NXAIncreaseInPrices"));
    }

    AVAERPriceListController operation;
    operation = new AVAERPriceListController(
        classStr(AVAERPriceListService),
        methodStr(AVAERPriceListService, generateReport),
        SysOperationExecutionMode::Synchronous);

    AVAERPriceListContract contract = operation.getDataContractObject();

    contract.initFromArgs(args);
    operation.startOperation();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_priceGroupId">_priceGroupId</param>
public static void constructForAzureBlob(PriceGroupId       _priceGroupId)
{
    if(!AVASalesParameters::find().ERPriceListFormat)
    {
        throw Error(strFmt("@NDX:NXAERPriceListReportError", "@NDX:NXASalesParameters", "@NDX:NXAIncreaseInPrices"));
    }

    AVAERPriceListController operation;
    operation = new AVAERPriceListController(
        classStr(AVAERPriceListService),
        methodStr(AVAERPriceListService, generateReport),
        SysOperationExecutionMode::Synchronous);

    AVAERPriceListContract contract = operation.getDataContractObject();


    contract.parmPrintToMemory(true);
    contract.initFromPriceGroup(_priceGroupId);
    operation.parmShowDialog(false);
    operation.startOperation();
}

/// <summary>
/// Gets caption of the dialog.
/// </summary>
/// <returns>Caption of the dialog</returns>
public ClassDescription defaultCaption()
{
    ClassDescription batchDescription;
    batchDescription = "@NDX:NXAPriceList";
    return batchDescription;
}
